from pathlib import Path
import ast,json,hashlib,os,time,subprocess,shutil
root=Path('/home/ubuntu/joxing/serial-native-teardown-20261102-01')
p=json.loads((root/'experiments/v0.0.11/serial-native-teardown-protocol.json').read_text())
vendors={n:subprocess.check_output(['git','rev-parse','HEAD'],cwd=root/'third_party'/n,text=True).strip() for n in p['upstream_commits']};assert vendors==p['upstream_commits']
gym=root/'experiments/v0.0.11/runtime/.venv/lib/python3.12/site-packages/gymnasium/core.py'
t=gym.read_text();lines=t.splitlines();methods=[]
for cls in ast.parse(t).body:
 if isinstance(cls,ast.ClassDef) and cls.name in ('Env','Wrapper'):
  for f in cls.body:
   if isinstance(f,ast.FunctionDef) and f.name=='close':methods.append({'class':cls.name,'line':f.lineno,'source':'\n'.join(lines[f.lineno-1:f.end_lineno])})
stance=root/'src/joxing/stance_env.py';assert not any(isinstance(n,ast.FunctionDef) and n.name=='close' for c in ast.parse(stance.read_text()).body if isinstance(c,ast.ClassDef) for n in c.body)
jobs=[]
for d in Path('/proc').iterdir():
 if not d.name.isdigit():continue
 try:
  cwd=str((d/'cwd').resolve());cmd=(d/'cmdline').read_bytes().replace(bytes([0]),b' ').decode(errors='replace')
  if (cwd.startswith('/home/ubuntu/joxing/') or '/home/ubuntu/joxing/' in cmd) and any(x in cmd for x in ['python','uv run','timeout']):jobs.append({'pid':int(d.name),'cwd':cwd,'command':cmd[:250]})
 except OSError:pass
assert not jobs
